SELECT item.icode, item.customicode, item.name, item.localitemname AS localitemname, item.manfcode, item.packunits, item.purprice, CASE (SELECT g.salepriceinitemlist FROM dbo.groups AS g WHERE (g.groupcode = $2)) WHEN 2 THEN item.saleprice2 WHEN 3 THEN item.saleprice3 WHEN 4 THEN item.saleprice4 WHEN 5 THEN item.saleprice5 ELSE item.saleprice END AS saleprice, manufacturer.name, (SELECT sum(godowndetail.currqty) FROM dbo.godowndetail WHERE (godowndetail.icode = item.icode)) AS stock, CASE WHEN ((SELECT salegodownstrategy FROM dbo.groups WHERE (groupcode = $2)) = 2) THEN (SELECT sum(godowndetail.currqty) FROM dbo.godowndetail WHERE ((godowndetail.icode = item.icode) AND (godowndetail.gcode = item.gcode))) ELSE (SELECT sum(godowndetail.currqty) FROM dbo.godowndetail, (SELECT DISTINCT gcode FROM dbo.groupallowedgodown WHERE ((groupallowedgodown.groupcode = $2) AND (groupallowedgodown.module = 1))) AS t WHERE ((godowndetail.icode = item.icode) AND (godowndetail.gcode = t.gcode))) END AS sstock, CASE WHEN ((SELECT purchasegodownstrategy FROM dbo.groups WHERE (groupcode = $2)) = 2) THEN (SELECT sum(godowndetail.currqty) FROM dbo.godowndetail WHERE ((godowndetail.icode = item.icode) AND (godowndetail.gcode = item.gcode))) ELSE (SELECT sum(godowndetail.currqty) FROM dbo.godowndetail, (SELECT DISTINCT gcode FROM dbo.groupallowedgodown WHERE ((groupallowedgodown.groupcode = $2) AND (groupallowedgodown.module = 3))) AS t WHERE ((godowndetail.icode = item.icode) AND (godowndetail.gcode = t.gcode))) END AS pstock, itempacking.name AS packing, item.packingdesc AS packingdesc, item.restricted, item.icatcode, item.iccode, item.packcode, item.itemalertcode, (SELECT ia.itemalerttypecode FROM dbo.itemalert AS ia WHERE (ia.itemalertcode = item.itemalertcode)) AS itemalerttypecode, item.isizecode, item.istylecode, item.icolourcode, item.iyarncode, item.isleevecode, item.ifabriccode, item.ibrandcode, item.ipartcode, item.oldpartcode, item.genericcode, item.location, (SELECT itempart.name FROM dbo.itempart WHERE (itempart.ipartcode = item.ipartcode)) AS itempartno, item.transitstock AS transitstock, (SELECT ia.bgcolor FROM dbo.itemalert AS ia WHERE (ia.itemalertcode = item.itemalertcode)) AS bgcolor FROM dbo.item LEFT JOIN dbo.itempacking ON ((item.packcode = itempacking.packcode)), dbo.manufacturer, (SELECT icatcode FROM dbo.itemcategory WHERE (((upper(dbo.fn_getpreference('GroupCategoryRights')))::citext = 'Y') AND (icatcode IN ($1))) UNION SELECT icatcode FROM dbo.itemcategory WHERE ((upper(dbo.fn_getpreference('GroupCategoryRights')))::citext = 'N') UNION SELECT 0 AS icatcode) AS p WHERE (((item.active = 1) AND (manufacturer.manfcode = item.manfcode)) AND (item.icatcode = p.icatcode)) ORDER BY item.name